69	/// One pool cell's outcome.
70	pub struct PoolResult {
71	    /// Wall-clock seconds from before the threads spawn to the
72	    /// consumer's last free.
73	    pub secs: f64,
74	    /// Fill counters over the whole cell, when the platform
75	    /// provides them.
76	    pub fills: Option<FillCounts>,
77	    /// `Inconsistent` results the cordyceps consumer retried,
78	    /// zero for the ring rows.
79	    pub inconsistent: u64,
80	}
81	
82	/// The message in a pool buffer for the ring rows: the sequence
83	/// number the consumer asserts, at the front of the buffer.
84	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable)]
85	#[repr(C)]
86	struct Msg {
87	    seq: u64,
88	}
89	
90	/// A pool buffer as bytes, the type the cordyceps row allocs
91	/// as, since its node holds atomics zerocopy cannot derive
92	/// over.
93	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable)]
94	#[repr(C)]
95	struct RawBuf([u8; CACHE_LINE_SIZE]);
96	
97	/// The cordyceps node laid over a pool buffer.
98	///
99	/// - `pool_link` is the buffer's first word, the pool's own
100	///   free-stack link, which the pool writes while the buffer is
101	///   free and the node leaves alone.
102	/// - `links` is the queue's, one atomic next pointer.
103	/// - `seq` is the payload the consumer asserts.
104	///
105	/// Fields are reached through raw pointers only, never a
106	/// reference to the whole node, since the pool writes the first
107	/// word behind the node's back once the buffer is freed.
108	#[repr(C)]
109	struct Node {
110	    pool_link: u64,
111	    links: Links<Node>,
112	    seq: u64,
113	}
114	
115	const _: () = assert!(size_of::<Node>() <= CACHE_LINE_SIZE);
116	
117	/// The queue's handle to a node: the pointer alone, since the
118	/// pool owns the storage and the consumer frees by index.
119	struct NodePtr(NonNull<Node>);
120	
121	// SAFETY: a node sits in a pool buffer that never moves while
122	// allocated, the handle is the pointer itself so `into_ptr` and
123	// `from_ptr` are identities, and `links` points at the node's
124	// own `Links` field.
125	unsafe impl Linked<Links<Node>> for Node {
126	    type Handle = NodePtr;
127	
128	    fn into_ptr(handle: NodePtr) -> NonNull<Node> {
129	        handle.0
130	    }
131	
132	    unsafe fn from_ptr(ptr: NonNull<Node>) -> NodePtr {
133	        NodePtr(ptr)
134	    }
135	
136	    unsafe fn links(target: NonNull<Node>) -> NonNull<Links<Node>> {
137	        // SAFETY: `target` is a live node, so its field address
138	        // is in bounds and non-null.
139	        unsafe { NonNull::new_unchecked(ptr::addr_of_mut!((*target.as_ptr()).links)) }
140	    }
141	}
142	
143	/// Bytes a pool of `pool_size` one-line buffers needs.
144	fn pool_region_size(pool_size: u32) -> u64 {
145	    size_of::<PoolHeader>() as u64 + pool_size as u64 * CACHE_LINE_SIZE as u64
146	}
147	
148	/// Run one pool cell: `count` messages through the loop at
149	/// `flavor`, a pool of `pool_size` buffers, and ring `depth`
150	/// (ignored by the cordyceps row), the producer on `pin.0` and
151	/// the consumer on `pin.1`, with the fill counters open across
152	/// it.
153	pub fn run_pool_cell(
154	    flavor: PoolFlavor,
155	    pin: Option<(usize, usize)>,
156	    pool_size: u32,
157	    depth: u32,
158	    count: u64,
159	) -> PoolResult {
160	    unpin_current();
161	    #[cfg(target_os = "linux")]
162	    let fills = crate::Fills::open();
163	    let (secs, inconsistent) = match flavor {
164	        PoolFlavor::SpscV2 => (cell_spsc_v2(pin, pool_size, depth, count), 0),
165	        PoolFlavor::MpscV1 => (cell_mpsc_v1(pin, pool_size, depth, count), 0),
166	        PoolFlavor::Cordyceps => cell_cordyceps(pin, pool_size, count),
167	    };
168	    #[cfg(target_os = "linux")]
169	    let fills = fills.and_then(crate::Fills::finish);
170	    #[cfg(not(target_os = "linux"))]
171	    let fills = None;
172	    PoolResult {
173	        secs,
174	        fills,
175	        inconsistent,
176	    }
177	}
