179	/// The SPSC v2 ring cell: descriptors cross a v2 ring of
180	/// `depth` line-sized slots.
181	fn cell_spsc_v2(pin: Option<(usize, usize)>, pool_size: u32, depth: u32, count: u64) -> f64 {
182	    use zc_ring_x1::spsc::v2::{Ring, region_size};
183	    let slot = CACHE_LINE_SIZE as u32;
184	    let mut region = LineBuf::new(region_size(slot, depth));
185	    let (mut tx, mut rx) = Ring::init(region.as_mut_bytes(), slot, depth)
186	        .expect("region sized by region_size and line-aligned") // OK: the region is the ring's own size and LineBuf is line-aligned
187	        .split();
188	    run_ring_cell(
189	        pin,
190	        pool_size,
191	        count,
192	        move |desc| {
193	            let mut slot = tx
194	                .reserve_slot_with::<Desc>(policy::spin)
195	                .expect("spin never gives up"); // OK: policy::spin never gives up
196	            *slot = desc;
197	            slot.commit();
198	        },
199	        move || {
200	            let slot = rx
201	                .reserve_slot_with::<Desc>(policy::spin)
202	                .expect("spin never gives up"); // OK: policy::spin never gives up
203	            let desc = *slot;
204	            slot.release();
205	            desc
206	        },
207	    )
208	}
209	
210	/// The MPSC v1 ring cell at 1p/1c: descriptors cross a v1 ring
211	/// of `depth` line-sized slots.
212	fn cell_mpsc_v1(pin: Option<(usize, usize)>, pool_size: u32, depth: u32, count: u64) -> f64 {
213	    use zc_ring_x1::mpsc::v1::{MpscRing, mpsc_region_size};
214	    let slot = CACHE_LINE_SIZE as u32;
215	    let mut region = LineBuf::new(mpsc_region_size(slot, depth));
216	    let (tx, mut rx) = MpscRing::init(region.as_mut_bytes(), slot, depth)
217	        .expect("region sized by mpsc_region_size and line-aligned") // OK: the region is the ring's own size and LineBuf is line-aligned
218	        .split();
219	    run_ring_cell(
220	        pin,
221	        pool_size,
222	        count,
223	        move |desc| {
224	            tx.send_with::<Desc>(policy::spin, |m| *m = desc)
225	                .expect("spin never gives up"); // OK: policy::spin never gives up
226	        },
227	        move || {
228	            let slot = rx
229	                .reserve_slot_with::<Desc>(policy::spin)
230	                .expect("spin never gives up"); // OK: policy::spin never gives up
231	            let desc = *slot;
232	            slot.release();
233	            desc
234	        },
235	    )
236	}
237	
238	/// The ring rows' loop over a pool of `pool_size` buffers: the
239	/// producer allocs, fills, converts the guard to a descriptor,
240	/// and hands it to `send`, and the consumer takes one from
241	/// `recv`, resolves it, asserts the sequence, and frees.
242	fn run_ring_cell(
243	    pin: Option<(usize, usize)>,
244	    pool_size: u32,
245	    count: u64,
246	    mut send: impl FnMut(Desc) + Send,
247	    mut recv: impl FnMut() -> Desc + Send,
248	) -> f64 {
249	    let mut pool_region = LineBuf::new(pool_region_size(pool_size));
250	    let mut pool = Pool::init(
251	        pool_region.as_mut_bytes(),
252	        CACHE_LINE_SIZE as u32,
253	        pool_size,
254	    )
255	    .expect("region sized for the pool and line-aligned"); // OK: the region is the pool's own size and LineBuf is line-aligned
256	    let mut registry = PoolRegistry::<1>::new();
257	    let pool_id = registry
258	        .register(pool.resolver())
259	        .expect("an empty registry has room"); // OK: capacity 1, nothing registered yet
260	    let registry = &registry;
261	
262	    let start = Instant::now();
263	    std::thread::scope(|s| {
264	        s.spawn(move || {
265	            if let Some((p, _)) = pin {
266	                pin_to_cpu(p);
267	            }
268	            for i in 0..count {
269	                let mut buf = pool
270	                    .alloc_with::<Msg>(policy::spin)
271	                    .expect("spin never gives up"); // OK: policy::spin never gives up
272	                buf.seq = i;
273	                let desc = registry
274	                    .into_desc(pool_id, buf)
275	                    .map_err(|(_, e)| e)
276	                    .expect("the guard is from the registered pool"); // OK: pool_id came from this registry's register
277	                send(desc);
278	            }
279	        });
280	        let consumer = s.spawn(move || {
281	            if let Some((_, c)) = pin {
282	                pin_to_cpu(c);
283	            }
284	            for i in 0..count {
285	                let desc = recv();
286	                // SAFETY: the descriptor was minted by the
287	                // producer's into_desc and read after the ring's
288	                // commit -> reserve handoff, and each is resolved
289	                // exactly once.
290	                let msg = unsafe { registry.resolve::<Msg>(desc) }
291	                    .expect("descriptors come from the producer's into_desc"); // OK: only the producer mints them, on this pool
292	                assert_eq!(msg.seq, i, "pool stream order broken");
293	                msg.free();
294	            }
295	        });
296	        consumer.join().expect("consumer panicked"); // OK: a panic in the consumer is the cell's failure
297	    });
298	    start.elapsed().as_secs_f64()
299	}
300	
301	/// The cordyceps cell: the queue links through the pool's
302	/// buffers. The producer allocs a buffer, lays the node over it,
303	/// and enqueues its pointer, and the consumer dequeues, asserts
304	/// the sequence, maps the pointer to the buffer's index, and
305	/// frees through the registry. Returns the seconds and the
306	/// `Inconsistent` results the consumer retried.
307	fn cell_cordyceps(pin: Option<(usize, usize)>, pool_size: u32, count: u64) -> (f64, u64) {
308	    let mut pool_region = LineBuf::new(pool_region_size(pool_size));
309	    let mut pool = Pool::init(
310	        pool_region.as_mut_bytes(),
311	        CACHE_LINE_SIZE as u32,
312	        pool_size,
313	    )
314	    .expect("region sized for the pool and line-aligned"); // OK: the region is the pool's own size and LineBuf is line-aligned
315	    let mut registry = PoolRegistry::<1>::new();
316	    let pool_id = registry
317	        .register(pool.resolver())
318	        .expect("an empty registry has room"); // OK: capacity 1, nothing registered yet
319	    let registry = &registry;
320	
321	    // Buffer 0's address, so the consumer can turn a node
322	    // pointer back into an index: alloc one, read its address
323	    // and index, and hand it back.
324	    let base = {
325	        let probe = pool
326	            .alloc::<RawBuf>()
327	            .expect("a fresh pool has a free buffer"); // OK: nothing allocated yet and pool_size is at least 1
328	        let addr = ptr::from_ref::<RawBuf>(&probe) as usize;
329	        let desc = registry
330	            .into_desc(pool_id, probe)
331	            .map_err(|(_, e)| e)
332	            .expect("the guard is from the registered pool"); // OK: pool_id came from this registry's register
333	        // SAFETY: the descriptor was minted just above and is
334	        // resolved once, on this thread.
335	        unsafe { registry.resolve::<RawBuf>(desc) }
336	            .expect("the descriptor was minted just above") // OK: same pool, index in range
337	            .free();
338	        addr - desc.buf_idx as usize * CACHE_LINE_SIZE
339	    };
340	
341	    // The stub the queue owns, leaked so it is static: a
342	    // handful of bytes per cell, and the queue's drop then
343	    // touches nothing the pool owns.
344	    let stub: &'static Node = Box::leak(Box::new(Node {
345	        pool_link: 0,
346	        links: Links::new_stub(),
347	        seq: 0,
348	    }));
349	    // SAFETY: the stub's links are `new_stub`, it is leaked so
350	    // it lives as long as the program, and nothing else touches
351	    // it.
352	    let queue = unsafe { MpscQueue::<Node>::new_with_static_stub(stub) };
353	    let queue = &queue;
354	
355	    let start = Instant::now();
356	    let inconsistent = std::thread::scope(|s| {
357	        s.spawn(move || {
358	            if let Some((p, _)) = pin {
359	                pin_to_cpu(p);
360	            }
361	            for i in 0..count {
362	                let mut buf = pool
363	                    .alloc_with::<RawBuf>(policy::spin)
364	                    .expect("spin never gives up"); // OK: policy::spin never gives up
365	                let node = ptr::from_mut::<RawBuf>(&mut buf).cast::<Node>();
366	                // Keep the buffer allocated without a guard: the
367	                // consumer frees it by index.
368	                registry
369	                    .into_desc(pool_id, buf)
370	                    .map_err(|(_, e)| e)
371	                    .expect("the guard is from the registered pool"); // OK: pool_id came from this registry's register
372	                // SAFETY: the buffer is line-aligned and at least
373	                // a node long, allocated to this thread until the
374	                // consumer frees it, and no reference to it
375	                // exists.
376	                unsafe {
377	                    ptr::addr_of_mut!((*node).links).write(Links::new());
378	                    ptr::addr_of_mut!((*node).seq).write(i);
379	                    queue.enqueue(NodePtr(NonNull::new_unchecked(node)));
380	                }
381	            }
382	        });
383	        let consumer = s.spawn(move || {
384	            if let Some((_, c)) = pin {
385	                pin_to_cpu(c);
386	            }
387	            let guard = queue.consume();
388	            let mut inconsistent = 0u64;
389	            for i in 0..count {
390	                let node = loop {
391	                    match guard.try_dequeue() {
392	                        Ok(node) => break node,
393	                        Err(TryDequeueError::Inconsistent) => {
394	                            inconsistent += 1;
395	                            std::hint::spin_loop();
396	                        }
397	                        Err(TryDequeueError::Empty) => std::hint::spin_loop(),
398	                        Err(TryDequeueError::Busy) => {
399	                            unreachable!("the consumer guard is held")
400	                        }
401	                    }
402	                };
403	                let node = node.0.as_ptr();
404	                // SAFETY: the node is the consumer's from the
405	                // dequeue until the free below, and the producer
406	                // wrote `seq` before its enqueue's release.
407	                let seq = unsafe { ptr::addr_of!((*node).seq).read() };
408	                assert_eq!(seq, i, "pool stream order broken");
409	                let idx = ((node as usize - base) / CACHE_LINE_SIZE) as u32;
410	                let desc = Desc {
411	                    pool_id: pool_id.as_u32(),
412	                    buf_idx: idx,
413	                };
414	                // SAFETY: the index is the buffer the producer
415	                // allocated for this node, resolved once, after
416	                // the dequeue's acquire.
417	                unsafe { registry.resolve::<RawBuf>(desc) }
418	                    .expect("the index is a buffer of this pool") // OK: computed from a pool buffer's address
419	                    .free();
420	            }
421	            inconsistent
422	        });
423	        consumer.join().expect("consumer panicked") // OK: a panic in the consumer is the cell's failure
424	    });
425	    (start.elapsed().as_secs_f64(), inconsistent)
426	}
