1	//! The pool-message sweep cells: the messaging layer's loop,
2	//! take a message from the pool, fill it, push its reference,
3	//! receive it, process it, return it, run over the descriptor
4	//! rings and cordyceps's intrusive queue on one pool, so the
5	//! queue is the only variable between rows.
6	//!
7	//! - The pool bounds the traffic: with `pool_size` buffers at
8	//!   most that many messages are in flight, so a ring depth at
9	//!   or above it never reports Full, and the cordyceps row,
10	//!   whose queue is unbounded, has no depth at all.
11	//! - Every row allocs from and frees to the same pool: the
12	//!   rings carry a `Desc`, cordyceps carries the buffer's
13	//!   pointer with the queue's link inside the buffer, and its
14	//!   consumer maps the pointer back to the buffer's index for
15	//!   the free.
16	//! - A cell moves a fixed count of messages, so its number is
17	//!   elapsed over count, the thread spawn inside it alike for
18	//!   every row, and the fill counters over the whole cell give
19	//!   the lines crossed per message.
20	
21	use std::ptr::{self, NonNull};
22	use std::time::Instant;
23	
24	use cordyceps::Linked;
25	use cordyceps::mpsc_queue::{Links, MpscQueue, TryDequeueError};
26	use tp_runner::{LineBuf, pin_to_cpu, unpin_current};
27	use zc_ring_x1::{CACHE_LINE_SIZE, Desc, Pool, PoolHeader, PoolRegistry, policy};
28	use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};
29	
30	use crate::FillCounts;
31	
32	/// The queue a pool cell runs the loop over.
33	#[derive(Clone, Copy, PartialEq, Eq)]
34	pub enum PoolFlavor {
35	    /// The SPSC v2 ring carrying descriptors.
36	    SpscV2,
37	    /// The MPSC v1 ring at 1p/1c carrying descriptors.
38	    MpscV1,
39	    /// cordyceps's `MpscQueue` linked through the pool's own
40	    /// buffers.
41	    Cordyceps,
42	}
43	
44	/// Every pool flavor, in table order.
45	pub const POOL_FLAVORS: [PoolFlavor; 3] = [
46	    PoolFlavor::SpscV2,
47	    PoolFlavor::MpscV1,
48	    PoolFlavor::Cordyceps,
49	];
50	
51	impl PoolFlavor {
52	    /// Lowercase name for labels.
53	    pub fn as_str(self) -> &'static str {
54	        match self {
55	            PoolFlavor::SpscV2 => "spsc-v2",
56	            PoolFlavor::MpscV1 => "mpsc-v1",
57	            PoolFlavor::Cordyceps => "cordyceps",
58	        }
59	    }
60	
61	    /// Whether the flavor has a ring depth to sweep. The
62	    /// cordyceps queue is unbounded, so its row runs once per
63	    /// pool size.
64	    pub fn has_depth(self) -> bool {
65	        !matches!(self, PoolFlavor::Cordyceps)
66	    }
67	}
68	
69	/// One pool cell's outcome.
70	pub struct PoolResult {
71	    /// Wall-clock seconds from before the threads spawn to the
72	    /// consumer's last free.
73	    pub secs: f64,
74	    /// Fill counters over the whole cell, when the platform
75	    /// provides them.
76	    pub fills: Option<FillCounts>,
77	    /// `Inconsistent` results the cordyceps consumer retried,
78	    /// zero for the ring rows.
79	    pub inconsistent: u64,
80	}
81	
82	/// The message in a pool buffer for the ring rows: the sequence
83	/// number the consumer asserts, at the front of the buffer.
84	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable)]
85	#[repr(C)]
86	struct Msg {
87	    seq: u64,
88	}
89	
90	/// A pool buffer as bytes, the type the cordyceps row allocs
91	/// as, since its node holds atomics zerocopy cannot derive
92	/// over.
93	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable)]
94	#[repr(C)]
95	struct RawBuf([u8; CACHE_LINE_SIZE]);
96	
97	/// The cordyceps node laid over a pool buffer.
98	///
99	/// - `pool_link` is the buffer's first word, the pool's own
100	///   free-stack link, which the pool writes while the buffer is
101	///   free and the node leaves alone.
102	/// - `links` is the queue's, one atomic next pointer.
103	/// - `seq` is the payload the consumer asserts.
104	///
105	/// Fields are reached through raw pointers only, never a
106	/// reference to the whole node, since the pool writes the first
107	/// word behind the node's back once the buffer is freed.
108	#[repr(C)]
109	struct Node {
110	    pool_link: u64,
111	    links: Links<Node>,
112	    seq: u64,
113	}
114	
115	const _: () = assert!(size_of::<Node>() <= CACHE_LINE_SIZE);
116	
117	/// The queue's handle to a node: the pointer alone, since the
118	/// pool owns the storage and the consumer frees by index.
119	struct NodePtr(NonNull<Node>);
120	
121	// SAFETY: a node sits in a pool buffer that never moves while
122	// allocated, the handle is the pointer itself so `into_ptr` and
123	// `from_ptr` are identities, and `links` points at the node's
124	// own `Links` field.
125	unsafe impl Linked<Links<Node>> for Node {
126	    type Handle = NodePtr;
127	
128	    fn into_ptr(handle: NodePtr) -> NonNull<Node> {
129	        handle.0
130	    }
131	
132	    unsafe fn from_ptr(ptr: NonNull<Node>) -> NodePtr {
133	        NodePtr(ptr)
134	    }
135	
136	    unsafe fn links(target: NonNull<Node>) -> NonNull<Links<Node>> {
137	        // SAFETY: `target` is a live node, so its field address
138	        // is in bounds and non-null.
139	        unsafe { NonNull::new_unchecked(ptr::addr_of_mut!((*target.as_ptr()).links)) }
140	    }
141	}
142	
143	/// Bytes a pool of `pool_size` one-line buffers needs.
144	fn pool_region_size(pool_size: u32) -> u64 {
145	    size_of::<PoolHeader>() as u64 + pool_size as u64 * CACHE_LINE_SIZE as u64
146	}
147	
148	/// Run one pool cell: `count` messages through the loop at
149	/// `flavor`, a pool of `pool_size` buffers, and ring `depth`
150	/// (ignored by the cordyceps row), the producer on `pin.0` and
151	/// the consumer on `pin.1`, with the fill counters open across
