1	//! tp-pool: run the pool-message loop over every placement,
2	//! flavor, ring depth, and pool size, a fixed count of messages
3	//! per cell, and emit one ns-per-message table per placement,
4	//! the pool sizes as columns and the flavor-by-depth rows, with
5	//! the fill counters beside it. The descriptor rings sweep
6	//! their depth, and the cordyceps row, an unbounded intrusive
7	//! queue, has none.
8	
9	use clap::Parser;
10	
11	use tp_matrix::pool::{POOL_FLAVORS, PoolFlavor, PoolResult, run_pool_cell};
12	use tp_runner::parse_depth;
13	use tp_runner::topo::{Placement, discover_placements};
14	
15	/// Banner: name, version, and tagline on one line, the first
16	/// line of every run and of `-h`/`--help`.
17	const TOP_ABOUT: &str = concat!(
18	    "tp-pool ",
19	    env!("CARGO_PKG_VERSION"),
20	    " - run the pool-message sweep, one table per placement"
21	);
22	
23	/// The tp-pool CLI.
24	#[derive(Parser, Debug)]
25	#[command(name = "tp-pool", version, about = TOP_ABOUT, max_term_width = 80)]
26	struct Cli {
27	    /// Pool sizes (buffers preallocated) to run, comma-separated,
28	    /// each a column
29	    ///
30	    /// The pool bounds the messages in flight, so this is the
31	    /// axis every flavor shares. Any count from 1 up.
32	    #[arg(
33	        long,
34	        value_name = "LIST",
35	        value_delimiter = ',',
36	        default_value = "1,100,1000",
37	        value_parser = parse_pool
38	    )]
39	    pool: Vec<u32>,
40	
41	    /// Ring depths (slots per ring) for the ring flavors,
42	    /// comma-separated powers of two, each a row per flavor
43	    ///
44	    /// A depth at or above the pool size never reports Full,
45	    /// so that row is the ring at the pool's bound and the rows
46	    /// below it are the ring throttling first.
47	    #[arg(
48	        long,
49	        value_name = "LIST",
50	        value_delimiter = ',',
51	        default_value = "1,8,64,1024",
52	        value_parser = parse_depth
53	    )]
54	    depth: Vec<u32>,
55	
56	    /// Messages per cell
57	    #[arg(long, value_name = "N", default_value_t = 1_000_000)]
58	    count: u64,
59	
60	    /// Runs per cell, the median reported
61	    #[arg(long, value_name = "N", default_value_t = 3, value_parser = parse_repeat)]
62	    repeat: usize,
63	}
64	
65	/// clap value parser for one `--pool` element: a count from 1
66	/// up.
67	fn parse_pool(s: &str) -> Result<u32, String> {
68	    let n: u32 = s.parse().map_err(|e| format!("{s}: {e}"))?;
69	    if n == 0 {
70	        return Err("pool size must be at least 1".to_string());
71	    }
72	    Ok(n)
73	}
74	
75	/// clap value parser for `--repeat`: a count from 1 up.
76	fn parse_repeat(s: &str) -> Result<usize, String> {
77	    let n: usize = s.parse().map_err(|e| format!("{s}: {e}"))?;
78	    if n == 0 {
79	        return Err("repeat must be at least 1".to_string());
80	    }
81	    Ok(n)
82	}
83	
84	/// One row of the tables: a flavor at a depth (`None` for the
85	/// depthless cordyceps row).
86	struct Row {
87	    flavor: PoolFlavor,
88	    depth: Option<u32>,
89	}
90	
91	/// The rows in table order: each ring flavor at every depth,
92	/// then the depthless ones.
93	fn rows(depths: &[u32]) -> Vec<Row> {
94	    let mut rows = Vec::new();
95	    for flavor in POOL_FLAVORS {
96	        if flavor.has_depth() {
97	            for &depth in depths {
98	                rows.push(Row {
99	                    flavor,
100	                    depth: Some(depth),
101	                });
102	            }
103	        } else {
104	            rows.push(Row {
105	                flavor,
106	                depth: None,
107	            });
108	        }
109	    }
110	    rows
111	}
112	
113	/// Run one cell `repeat` times and keep the median by elapsed
114	/// time, its fill counters with it.
115	fn median_cell(
116	    flavor: PoolFlavor,
117	    pin: Option<(usize, usize)>,
118	    pool_size: u32,
119	    depth: u32,
120	    count: u64,
121	    repeat: usize,
122	) -> PoolResult {
123	    let mut runs: Vec<PoolResult> = (0..repeat)
124	        .map(|_| run_pool_cell(flavor, pin, pool_size, depth, count))
125	        .collect();
126	    runs.sort_by(|a, b| a.secs.total_cmp(&b.secs));
127	    runs.swap_remove(runs.len() / 2)
128	}
129	
130	/// Print `rows` as an aligned markdown table under `headers`.
131	/// The first two columns left-aligned, the rest right-aligned.
132	fn print_table(headers: &[String], rows: &[Vec<String>]) {
133	    let mut w: Vec<usize> = headers.iter().map(|h| h.len()).collect();
134	    for row in rows {
135	        for (i, cell) in row.iter().enumerate() {
136	            w[i] = w[i].max(cell.len());
137	        }
138	    }
139	    let fmt_row = |cells: &[String]| {
140	        let mut line = String::from("|");
141	        for (i, cell) in cells.iter().enumerate() {
142	            if i < 2 {
143	                line.push_str(&format!(" {:<w$} |", cell, w = w[i]));
144	            } else {
145	                line.push_str(&format!(" {:>w$} |", cell, w = w[i]));
146	            }
147	        }
148	        line
149	    };
150	    println!("{}", fmt_row(headers));
151	    let mut sep = String::from("|");
152	    for (i, width) in w.iter().enumerate() {
153	        if i < 2 {
154	            sep.push_str(&format!("{}|", "-".repeat(width + 2)));
155	        } else {
156	            sep.push_str(&format!("{}:|", "-".repeat(width + 1)));
157	        }
158	    }
159	    println!("{sep}");
160	    for row in rows {
161	        println!("{}", fmt_row(row));
162	    }
163	}
164	
165	/// `fills/msg` cell: 3 decimals, or 4 when the value is tiny,
166	/// `-` when counters were unavailable.
167	fn fills_cell(res: &PoolResult, count: u64) -> String {
168	    match &res.fills {
169	        Some(f) => {
170	            let v = f.lcl_cache as f64 / count.max(1) as f64;
171	            if v < 0.01 {
172	                format!("{v:.4}")
173	            } else {
174	                format!("{v:.3}")
175	            }
176	        }
177	        None => "-".to_string(),
178	    }
179	}
180	
181	/// Entry point: banner, run the sweep, emit the tables.
182	fn main() {
183	    let cli = Cli::parse();
184	    println!("{TOP_ABOUT}");
185	    let placements = discover_placements();
186	    let rows = rows(&cli.depth);
187	    println!(
188	        "{} cells, {} messages each, median of {} runs; ns/msg = elapsed over messages; \
189	         fills/msg = cross-core cache-line fills per message",
190	        placements.len() * rows.len() * cli.pool.len(),
191	        cli.count,
192	        cli.repeat,
193	    );
194	
195	    let mut headers = vec!["flavor".to_string(), "depth".to_string()];
196	    headers.extend(cli.pool.iter().map(|x| format!("pool={x}")));
197	
198	    for (i, placement) in placements.iter().enumerate() {
199	        let Placement { label, pin } = placement;
200	        // Two blank lines between placements, so one placement's
201	        // tables stand apart from the next one's progress lines.
202	        if i > 0 {
203	            println!();
204	            println!();
205	        }
206	        let mut ns_rows: Vec<Vec<String>> = Vec::new();
207	        let mut fill_rows: Vec<Vec<String>> = Vec::new();
208	        for row in &rows {
209	            let depth_label = row.depth.map_or("-".to_string(), |d| d.to_string());
210	            let mut ns_row = vec![row.flavor.as_str().to_string(), depth_label.clone()];
211	            let mut fill_row = ns_row.clone();
212	            for &pool_size in &cli.pool {
213	                eprintln!(
214	                    "pool {label} {} depth {depth_label} pool {pool_size} ...",
215	                    row.flavor.as_str()
216	                );
217	                let res = median_cell(
218	                    row.flavor,
219	                    *pin,
220	                    pool_size,
221	                    row.depth.unwrap_or(1),
222	                    cli.count,
223	                    cli.repeat,
224	                );
225	                ns_row.push(format!("{:.1}", res.secs * 1e9 / cli.count.max(1) as f64));
226	                fill_row.push(fills_cell(&res, cli.count));
227	            }
228	            ns_rows.push(ns_row);

