1	//! tp-pool: run the pool-message loop over every placement,
2	//! flavor, ring depth, and pool size, each cell for a duration,
3	//! and emit one ns-per-message table per placement,
4	//! the pool sizes as columns and the flavor-by-depth rows, with
5	//! the fill counters beside it. The descriptor rings sweep
6	//! their depth, and the cordyceps row, an unbounded intrusive
7	//! queue, has none.
8	
9	use std::time::Duration;
10	
11	use clap::Parser;
12	
13	use tp_matrix::pool::{POOL_FLAVORS, PoolFlavor, PoolResult, run_pool_cell};
14	use tp_matrix::{PLACEMENT_MEANING, XFILLS_MEANING, print_legend};
15	use tp_runner::parse_depth;
16	use tp_runner::topo::{Placement, discover_placements};
17	
18	/// Banner: name, version, and tagline on one line, the first
19	/// line of every run and of `-h`/`--help`.
20	const TOP_ABOUT: &str = concat!(
21	    "tp-pool ",
22	    env!("CARGO_PKG_VERSION"),
23	    " - run the pool-message sweep, one table per placement"
24	);
25	
26	/// The tp-pool CLI.
27	#[derive(Parser, Debug)]
28	#[command(name = "tp-pool", version, about = TOP_ABOUT, max_term_width = 80)]
29	struct Cli {
30	    /// Pool sizes (buffers preallocated) to run, comma-separated,
31	    /// each a column
32	    ///
33	    /// The pool bounds the messages in flight, so this is the
34	    /// axis every flavor shares. Any count from 1 up.
35	    #[arg(
36	        long,
37	        value_name = "LIST",
38	        value_delimiter = ',',
39	        default_value = "1,100,1000",
40	        value_parser = parse_pool
41	    )]
42	    pool: Vec<u32>,
43	
44	    /// Ring depths (slots per ring) for the ring flavors,
45	    /// comma-separated powers of two, each a row per flavor
46	    ///
47	    /// A depth at or above the pool size never reports Full,
48	    /// so that row is the ring at the pool's bound and the rows
49	    /// below it are the ring throttling first.
50	    #[arg(
51	        long,
52	        value_name = "LIST",
53	        value_delimiter = ',',
54	        default_value = "1,8,64,1024",
55	        value_parser = parse_depth
56	    )]
57	    depth: Vec<u32>,
58	
59	    /// Wall-clock seconds per cell run
60	    #[arg(
61	        short = 'd',
62	        long = "duration",
63	        value_name = "SECS",
64	        default_value_t = 0.1,
65	        value_parser = parse_duration
66	    )]
67	    duration: f64,
68	
69	    /// Runs per cell, the median reported
70	    #[arg(long, value_name = "N", default_value_t = 3, value_parser = parse_repeat)]
71	    repeat: usize,
72	
73	    /// Print a legend after the last placement explaining every
74	    /// table and column
75	    #[arg(short = 'v', long)]
76	    verbose: bool,
77	}
78	
79	/// clap value parser for one `--pool` element: a count from 1
80	/// up.
81	fn parse_pool(s: &str) -> Result<u32, String> {
82	    let n: u32 = s.parse().map_err(|e| format!("{s}: {e}"))?;
83	    if n == 0 {
84	        return Err("pool size must be at least 1".to_string());
85	    }
86	    Ok(n)
87	}
88	
89	/// clap value parser for `--duration`: seconds above zero.
90	fn parse_duration(s: &str) -> Result<f64, String> {
91	    let secs: f64 = s.parse().map_err(|e| format!("{s}: {e}"))?;
92	    if !(secs > 0.0 && secs.is_finite()) {
93	        return Err("duration must be a number of seconds above 0".to_string());
94	    }
95	    Ok(secs)
96	}
97	
98	/// clap value parser for `--repeat`: a count from 1 up.
99	fn parse_repeat(s: &str) -> Result<usize, String> {
100	    let n: usize = s.parse().map_err(|e| format!("{s}: {e}"))?;
101	    if n == 0 {
102	        return Err("repeat must be at least 1".to_string());
103	    }
104	    Ok(n)
105	}
106	
107	/// One row of the tables: a flavor at a depth (`None` for the
108	/// depthless cordyceps row).
109	struct Row {
110	    flavor: PoolFlavor,
111	    depth: Option<u32>,
112	}
113	
114	/// The rows in table order: each ring flavor at every depth,
115	/// then the depthless ones.
116	fn rows(depths: &[u32]) -> Vec<Row> {
117	    let mut rows = Vec::new();
118	    for flavor in POOL_FLAVORS {
119	        if flavor.has_depth() {
120	            for &depth in depths {
121	                rows.push(Row {
122	                    flavor,
123	                    depth: Some(depth),
124	                });
125	            }
126	        } else {
127	            rows.push(Row {
128	                flavor,
129	                depth: None,
130	            });
131	        }
132	    }
133	    rows
134	}
135	
136	/// Run one cell `repeat` times and keep the median by ns per
137	/// message, its fill counters with it.
138	fn median_cell(
139	    flavor: PoolFlavor,
140	    pin: Option<(usize, usize)>,
141	    pool_size: u32,
142	    depth: u32,
143	    dur: Duration,
144	    repeat: usize,
145	) -> PoolResult {
146	    let mut runs: Vec<PoolResult> = (0..repeat)
147	        .map(|_| run_pool_cell(flavor, pin, pool_size, depth, dur))
148	        .collect();
149	    runs.sort_by(|a, b| ns_per_msg(a).total_cmp(&ns_per_msg(b)));
150	    runs.swap_remove(runs.len() / 2)
151	}
152	
153	/// Print `rows` as an aligned markdown table under `headers`.
154	/// The first two columns left-aligned, the rest right-aligned.
155	/// Returns the table's width in characters.
156	fn print_table(headers: &[String], rows: &[Vec<String>]) -> usize {
157	    let mut w: Vec<usize> = headers.iter().map(|h| h.len()).collect();
158	    for row in rows {
159	        for (i, cell) in row.iter().enumerate() {
160	            w[i] = w[i].max(cell.len());
161	        }
162	    }
163	    let fmt_row = |cells: &[String]| {
164	        let mut line = String::from("|");
165	        for (i, cell) in cells.iter().enumerate() {
166	            if i < 2 {
167	                line.push_str(&format!(" {:<w$} |", cell, w = w[i]));
168	            } else {
169	                line.push_str(&format!(" {:>w$} |", cell, w = w[i]));
170	            }
171	        }
172	        line
173	    };
174	    println!("{}", fmt_row(headers));
175	    let mut sep = String::from("|");
176	    for (i, width) in w.iter().enumerate() {
177	        if i < 2 {
178	            sep.push_str(&format!("{}|", "-".repeat(width + 2)));
179	        } else {
180	            sep.push_str(&format!("{}:|", "-".repeat(width + 1)));
181	        }
182	    }
183	    println!("{sep}");
184	    for row in rows {
185	        println!("{}", fmt_row(row));
186	    }
187	    sep.len()
188	}
189	
190	/// A run's elapsed ns over the messages it moved.
191	fn ns_per_msg(res: &PoolResult) -> f64 {
192	    res.secs * 1e9 / res.msgs.max(1) as f64
193	}
194	
195	/// `xfills/msg` cell: 3 decimals, or 4 when the value is tiny,
196	/// `-` when counters were unavailable.
197	fn fills_cell(res: &PoolResult) -> String {
198	    match &res.fills {
199	        Some(f) => {
200	            let v = f.lcl_cache as f64 / res.msgs.max(1) as f64;
201	            if v < 0.01 {
202	                format!("{v:.4}")
203	            } else {
204	                format!("{v:.3}")
205	            }
206	        }
207	        None => "-".to_string(),
208	    }
209	}
210	
211	/// Entry point: banner, run the sweep, emit the tables, and
212	/// the legend once after the last placement.
213	fn main() {
214	    let cli = Cli::parse();
215	    println!("{TOP_ABOUT}");
216	    let placements = discover_placements();
217	    let rows = rows(&cli.depth);
218	    println!(
219	        "{} cells, {:.1}s each, median of {} runs{}",
220	        placements.len() * rows.len() * cli.pool.len(),
221	        cli.duration,
222	        cli.repeat,
223	        if cli.verbose { "" } else { "; -v for a legend" },
224	    );
225	
226	    let mut headers = vec!["flavor".to_string(), "depth".to_string()];
227	    headers.extend(cli.pool.iter().map(|x| format!("pool={x}")));
228	
229	    let mut width = 0;
230	    for (i, placement) in placements.iter().enumerate() {
231	        let Placement { label, pin } = placement;
232	        // Two blank lines between placements, so one placement's
233	        // tables stand apart from the next one's progress lines.
234	        if i > 0 {
235	            println!();
236	            println!();
237	        }
238	        let mut ns_rows: Vec<Vec<String>> = Vec::new();

